mapper.select:

WHERE t.grade = #{grade} AND t.status = 'PUBLISHED' AND t.week_start <= #{weekStart}
ORDER BY t.week_start DESC
LIMIT 1

SELECT id FROM weekly_theme

ORDER BY week_start DESC, grade, created_at DESC, id
LIMIT #{size} OFFSET #{offset}

SELECT id, version, title, intro, outro, intro_image_uri, outro_image_uri, intro_video_uri, outro_video_uri,
       intro_motion, outro_motion, big_question, candidates, answer, answer_clue
FROM weekly_theme_version WHERE id = #{versionId}

mapper.update:
UPDATE weekly_theme
SET grade = #{grade}, week_start = #{weekStart}, status = #{status},
    current_version_id = #{currentVersionId}, updated_at = #{now}
WHERE id = #{id}

UPDATE weekly_theme
SET status = 'PUBLISHED', published_version_id = current_version_id, published_at = #{now}, updated_at = #{now}
WHERE id = #{id}
